"use client";

import { useEffect, useState, type ReactNode } from "react";
import { Icon } from "@/components/nx/Icon";
import { VpsHero, VpsStateBanner } from "./VpsHero";
import { SubNav, type SubSection } from "./ui";
import type { VpsHeaderData } from "./types";

/**
 * The VPS panel's shell: a pinned identity hero, a pinned tab rail, one tab.
 *
 * TEN TABS TO EIGHT.
 * - Metrics folded into Overview. The old dashboard reported CPU and memory in
 *   three places that could not agree — a hypervisor instant, RRD history, and
 *   an in-guest process snapshot.
 * - Snapshots merged into Backups: both answer "put this machine back how it
 *   was", differing in mechanism, not intent.
 * - Upgrade folded into Settings. Resizing is a setting, not a destination; it
 *   does not belong in a rail beside Console and Files as though it were
 *   visited daily. Reinstall went with it, for the same reason.
 * - "Control panel" renamed Services, for what it actually manages.
 *
 * Every tab with sub-sections uses the side rail from GameSettingsShell rather
 * than a second row of pills, so Backups, Networking, Activity and Settings all
 * navigate the same way.
 */

type TabKey =
  | "overview" | "console" | "files" | "services"
  | "backups" | "networking" | "activity" | "settings";

const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview",   label: "Overview",   icon: "donut" },
  { key: "console",    label: "Console",    icon: "terminal" },
  { key: "files",      label: "Files",      icon: "folder" },
  { key: "services",   label: "Services",   icon: "sliders" },
  { key: "backups",    label: "Backups",    icon: "archive" },
  { key: "networking", label: "Networking", icon: "nodes" },
  { key: "activity",   label: "Activity",   icon: "activity" },
  { key: "settings",   label: "Settings",   icon: "gear" },
];

/** Retired keys that links, bookmarks and worker notifications still use. */
const ALIASES: Record<string, TabKey> = {
  resize: "settings",
  upgrade: "settings",
  reinstall: "settings",
  metrics: "overview",
  snapshots: "backups",
  "control panel": "services",
  controlpanel: "services",
  cpanel: "services",
};

function resolveTab(raw: string | undefined): TabKey {
  const k = (raw ?? "").toLowerCase().trim();
  if (TABS.some((t) => t.key === k)) return k as TabKey;
  return ALIASES[k] ?? "overview";
}

const RESTORE: SubSection<"backups" | "snapshots">[] = [
  { key: "backups", label: "Backups", sub: "Full archives you can restore", icon: "archive" },
  { key: "snapshots", label: "Snapshots", sub: "Point-in-time disk state", icon: "layers" },
];

const HISTORY: SubSection<"jobs" | "access">[] = [
  { key: "jobs", label: "Server jobs", sub: "What we ran for you", icon: "activity" },
  { key: "access", label: "SSH access", sub: "Sign-ins and failures", icon: "key" },
];

export function VpsPanelShell({
  data, busy, suspendReason, provisionError,
  overviewPanel, consolePanel, filesPanel, servicesPanel,
  backupsPanel, snapshotsPanel, networkingPanel, settingsPanel,
  activityPanel, accessPanel, initialTab,
}: {
  data: VpsHeaderData;
  /** A job is in flight — power controls disable themselves. */
  busy: boolean;
  suspendReason: string | null;
  provisionError: string | null;
  overviewPanel: ReactNode;
  consolePanel: ReactNode;
  filesPanel: ReactNode;
  servicesPanel: ReactNode;
  backupsPanel: ReactNode;
  snapshotsPanel: ReactNode;
  networkingPanel: ReactNode;
  settingsPanel: ReactNode;
  activityPanel: ReactNode;
  accessPanel: ReactNode;
  initialTab?: string;
}) {
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));

  useEffect(() => {
    const onPop = () => {
      const t = new URLSearchParams(window.location.search).get("tab") ?? undefined;
      setTab(resolveTab(t));
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const go = (t: TabKey) => {
    setTab(t);
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    window.history.pushState(null, "", url);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    /* A max-width on the panel. At full bleed on a wide monitor the cards
       stretch to fill 1500px+ and read as banners rather than cards; this pulls
       the column in so they keep a card's proportions. */
    <div className="mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      <VpsStateBanner data={data} suspendReason={suspendReason} provisionError={provisionError} />

      <div className="sticky top-0 z-20 -mx-1 flex flex-col gap-2 bg-[color-mix(in_srgb,var(--color-bg)_82%,transparent)] px-1 pb-2 pt-1 backdrop-blur-xl">
        <VpsHero data={data} busy={busy} />

        <nav className="flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-surface p-1.5">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => go(t.key)}
                aria-current={on ? "page" : undefined}
                className={
                  "inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-semibold transition " +
                  (on
                    ? "bg-[linear-gradient(120deg,rgba(80,40,190,.55),rgba(30,44,130,.42))] text-[#fff] shadow-[inset_0_0_0_1px_rgba(139,92,255,.5)]"
                    : "text-tx-dim hover:bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] hover:text-tx")
                }
              >
                <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-[#fff]" : "text-tx-dim"} />
                {t.label}
              </button>
            );
          })}
        </nav>
      </div>

      <div className="min-w-0">
        {tab === "overview" && overviewPanel}
        {tab === "console" && consolePanel}
        {tab === "files" && filesPanel}
        {tab === "services" && servicesPanel}
        {tab === "networking" && networkingPanel}
        {tab === "settings" && settingsPanel}

        {tab === "backups" && (
          <SubNav sections={RESTORE} slots={{ backups: backupsPanel, snapshots: snapshotsPanel }} />
        )}

        {tab === "activity" && (
          <SubNav sections={HISTORY} slots={{ jobs: activityPanel, access: accessPanel }} />
        )}
      </div>
    </div>
  );
}
