  PROVISIONING: { tone: "busy", label: "Provisioning", live: true },
  PENDING:      { tone: "busy", label: "Provisioning", live: true },
  REINSTALLING: { tone: "busy", label: "Reinstalling", live: true },
  DELETING:     { tone: "idle", label: "Deleting",     live: true },
  ERROR:        { tone: "bad",  label: "Failed",       live: false },
};

function Spec({ icon, value, label }: { icon: string; value: string; label: string }) {
  return (
    <span className="flex items-center gap-2">
      <Icon name={icon} size={15} className="flex-none text-[#7f9ad0]" />
      <span className="flex flex-col leading-tight">
