"use client";

import { useState, useTransition } from "react";
import { serverAction } from "@/lib/actions";
import { Icon } from "@/components/nx/Icon";
import { Menu, Confirm } from "./kit";

/**
 * Power, prioritised.
 *
 * The control set this replaces put Start, Reboot, Stop, Reinstall and Delete
 * in one flat row of equal-weight buttons, so wiping the machine sat a few
 * pixels from restarting it and looked exactly as routine. Here:
 *
 *   primary    — Open terminal (the thing people come to do)
 *   secondary  — Reboot / Stop, quiet buttons
 *   behind More — Reinstall and Delete, each gated by a typed confirmation
 *
 * Same `serverAction` calls underneath; only the weighting changed. The typed
 * confirmation is deliberately not a window.confirm — a native dialog is the
 * one piece of UI a customer clicks through on reflex.
 */

export function VpsPowerControls({ serverId, serverName, status, busy, terminalSlot }: {
  serverId: string;
  serverName: string;
  status: string;
  busy: boolean;
  /** The existing OpenTerminalButton — primary action. */
  terminalSlot: React.ReactNode;
}) {
  const [error, setError] = useState<string | null>(null);
  const [ask, setAsk] = useState<"reinstall" | "delete" | "stop" | null>(null);
  const [pending, start] = useTransition();
  const disabled = pending || busy;
  const running = status === "RUNNING";

  const run = (action: string) => {
    setError(null);
    start(async () => {
      const res = await serverAction(serverId, action);
      if (res?.error) setError(res.error);
    });
  };

  /* Each action reads as itself: reboot is amber-tinted caution, stop is
     rose, start is the go action, More is neutral. A row of five identical
     grey buttons is what made Delete look as routine as Reboot. */
  const base =
    "inline-flex items-center gap-1.5 rounded-[10px] border px-3.5 py-2 text-[12.5px] font-bold transition disabled:opacity-40 disabled:cursor-not-allowed";
  const amber = `${base} border-amber-400/35 bg-amber-500/[0.10] text-amber-200 hover:border-amber-400/60 hover:bg-amber-500/[0.16]`;
  const rose  = `${base} border-rose-400/35 bg-rose-500/[0.10] text-rose-200 hover:border-rose-400/60 hover:bg-rose-500/[0.16]`;
  const mint  = `${base} border-emerald-400/35 bg-emerald-500/[0.10] text-emerald-200 hover:border-emerald-400/60 hover:bg-emerald-500/[0.16]`;

  return (
    <div className="flex flex-none flex-col items-end gap-2">
      <div className="flex flex-wrap items-center gap-2">
        {terminalSlot}

        {!running && (
          <button type="button" disabled={disabled} onClick={() => run("start")} className={mint}>
            <Icon name="bolt" size={14} tone="inherit" /> Start
          </button>
        )}
        {running && (
          <>
            <button type="button" disabled={disabled} onClick={() => run("reboot")} className={amber}>
              <Icon name="refresh" size={14} tone="inherit" /> Reboot
            </button>
            <button type="button" disabled={disabled} onClick={() => setAsk("stop")} className={rose}>
              <Icon name="xcircle" size={14} tone="inherit" /> Stop
            </button>
          </>
        )}

        <Menu
          label="More"
          items={[
            { key: "reinstall", label: "Reinstall OS…", icon: "refresh2", danger: true, onSelect: () => setAsk("reinstall") },
            { key: "delete", label: "Delete server…", icon: "trash", danger: true, onSelect: () => setAsk("delete") },
          ]}
        />
      </div>

      {error && (
        <p className="text-[11.5px] text-rose-300" role="alert">{error}</p>
      )}

      {/* Disabled controls with no stated reason are the worst kind: the
          customer cannot tell a broken button from a busy one. */}
      {busy && !error && (
        <p className="flex items-center gap-1.5 text-[11.5px] text-tx-faint">
          <Icon name="refresh2" size={12} className="nx-spin" />
          A job is running on this server — power controls come back when it finishes.
        </p>
      )}

      {/* Stopping is reversible, so it asks once without ceremony. */}
      <Confirm
        open={ask === "stop"}
        title="Stop this server?"
        body="It will power off until you start it again. Anything running inside stops with it."
        confirmLabel="Stop server"
        onConfirm={() => run("stop")}
        onClose={() => setAsk(null)}
      />

      <Confirm
        open={ask === "reinstall"}
        danger
        typeToConfirm={serverName}
        title="Reinstall the operating system?"
        body={
          <>
            This wipes <span className="font-bold text-tx">everything</span> on the disk and
            redeploys a fresh OS. Files, databases, configuration and installed software are all
            destroyed. Backups taken before now are unaffected.
          </>
        }
        confirmLabel="Wipe and reinstall"
        onConfirm={() => run("reinstall")}
        onClose={() => setAsk(null)}
      />

      <Confirm
        open={ask === "delete"}
        danger
        typeToConfirm={serverName}
        title="Delete this server permanently?"
        body={
          <>
            The machine and its disk are destroyed and cannot be recovered — not by us, not from a
            snapshot. Any remaining term is handled by the cancellation flow under Settings, which
            shows your refund first.
          </>
        }
        confirmLabel="Delete permanently"
        onConfirm={() => run("delete")}
        onClose={() => setAsk(null)}
      />
    </div>
  );
}

