/**
 * The resource monitor.
 *
 * "All" overlays every series on one normalised 0–100% axis with a legend
 * beneath; the individual views drop to one series in its own units. Normalising
 * is the only honest way to put bytes and percentages on one axis — the legend
 * says so, and each series keeps its real value in the tooltip.
 *
 * Source is /api/metrics (Proxmox RRD) for CPU, memory and network, and
 * /api/servers/[id]/disk for disk, which the hypervisor cannot see for a QEMU
 * guest. A window with no samples says so rather than drawing a flat zero.
 */

type Row = { time: number; cpu: number | null; mem: number | null; maxmem: number | null; netin: number | null; netout: number | null };
type DiskPt = { time: number; disk: number; maxdisk: number };
type TF = "hour" | "day" | "week" | "month";
type View = "all" | "cpu" | "ram" | "disk" | "net";

const RANGES: { key: TF; label: string }[] = [
  { key: "hour", label: "1H" },
  { key: "day", label: "24H" },
  { key: "week", label: "7D" },
  { key: "month", label: "30D" },
];

const VIEWS: { key: View; label: string }[] = [
  { key: "all", label: "All" },
  { key: "cpu", label: "CPU" },
  { key: "ram", label: "RAM" },
  { key: "disk", label: "Disk" },
  { key: "net", label: "Network" },
];

const SERIES: Record<Exclude<View, "all">, { label: string; colour: string; glow: string }> = {
  cpu:  { label: "CPU",     colour: "#38bdf8", glow: "rgba(56,189,248,.35)" },
  ram:  { label: "RAM",     colour: "#a78bfa", glow: "rgba(167,139,250,.35)" },
  disk: { label: "Disk",    colour: "#34d399", glow: "rgba(52,211,153,.35)" },
  net:  { label: "Network", colour: "#f472b6", glow: "rgba(244,114,182,.35)" },
};

export function VpsResourceMonitor({ serverId, available }: { serverId: string; available: boolean }) {
  const [tf, setTf] = useState<TF>("day");
  const [view, setView] = useState<View>("all");
  const [rows, setRows] = useState<Row[] | null>(null);
  const [disk, setDisk] = useState<DiskPt[] | null>(null);
  const [failed, setFailed] = useState(false);
  const [hover, setHover] = useState<number | null>(null);
  const svgRef = useRef<SVGSVGElement | null>(null);

  useEffect(() => {
    if (!available) return;
    let alive = true;
    setRows(null); setFailed(false);
    fetch(`/api/metrics?serverId=${serverId}&tf=${tf}`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error())))
      .then((j) => { if (alive) setRows(Array.isArray(j.data) ? j.data : []); })
      .catch(() => { if (alive) setFailed(true); });
    return () => { alive = false; };
  }, [serverId, tf, available]);

  useEffect(() => {
    if (!available) return;
    let alive = true;
    fetch(`/api/servers/${serverId}/disk`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error())))
      .then((j) => { if (alive) setDisk(Array.isArray(j.data) ? j.data : []); })
      .catch(() => { if (alive) setDisk([]); });
    return () => { alive = false; };
  }, [serverId, available]);

  /** Each series normalised to 0–100 for the overlay, with a formatter that
   *  can put the real value back for the tooltip. */
  const data = useMemo(() => {
    if (!rows) return null;
    const clean = rows.filter((r) => r.cpu !== null || r.mem !== null);
    if (clean.length < 2) return { ok: false as const };

    const maxmem = clean.find((r) => r.maxmem)?.maxmem ?? 0;
    const nets = clean.map((r) => (r.netin ?? 0) + (r.netout ?? 0));
    const netMax = Math.max(...nets, 1);

    /* Disk is sampled on its own cadence, so it is resampled onto the metric
       timestamps by nearest neighbour rather than assumed to line up. */
    const diskPct = clean.map((r) => {
      if (!disk || disk.length === 0) return null;
      let best = disk[0];
      for (const d of disk) if (Math.abs(d.time - r.time) < Math.abs(best.time - r.time)) best = d;
      return best.maxdisk ? (best.disk / best.maxdisk) * 100 : null;
    });

    return {
      ok: true as const,
      n: clean.length,
      labels: clean.map((r) =>
        new Date(r.time * 1000).toLocaleString(undefined, {
          hour: "2-digit", minute: "2-digit",
          ...(tf === "week" || tf === "month" ? { day: "numeric", month: "short" } : {}),
        }),
      ),
      cpu:  { norm: clean.map((r) => (r.cpu ?? 0) * 100), real: clean.map((r) => `${((r.cpu ?? 0) * 100).toFixed(1)}%`) },
      ram:  { norm: clean.map((r) => (maxmem ? ((r.mem ?? 0) / maxmem) * 100 : 0)), real: clean.map((r) => fmtBytes(r.mem ?? 0)) },
      disk: { norm: diskPct.map((d) => d ?? 0), real: diskPct.map((d) => (d === null ? "—" : `${d.toFixed(1)}%`)), missing: diskPct.every((d) => d === null) },
      net:  { norm: nets.map((v) => (v / netMax) * 100), real: nets.map((v) => `${fmtBytes(v)}/s`) },
    } as const;
  }, [rows, disk, tf]);

  const header = (
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.07] px-4 py-2.5">
      <Segmented value={view} onChange={setView} items={VIEWS} size="sm" />
      <Segmented value={tf} onChange={setTf} items={RANGES} size="sm" />
    </div>
  );

  const frame = (body: React.ReactNode) => (

export function VpsOverviewPanel({
  data, base, activity, subscription, backups, sftpCommand, sshPort,
}: {
  data: VpsHeaderData;
  base: string;
  activity: ReactNode;
  subscription: ReactNode;
  backups: ReactNode;
