  const [diskPct, setDiskPct] = useState<number | null>(null);
  const [diskLabel, setDiskLabel] = useState<string | null>(null);
  const graphable = data.status === "RUNNING" || data.status === "STOPPED";

  /* Disk is the one figure the hypervisor cannot answer for a QEMU guest, so
     it is read from the sample API on the client and stays null until it
     arrives — never 0, which would read as an empty disk. */
  useEffect(() => {
    if (!graphable) return;
    let alive = true;
    fetch(`/api/servers/${data.serverId}/disk`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error())))
      .then((j) => {
        if (!alive) return;
        const last = Array.isArray(j.data) && j.data.length ? j.data[j.data.length - 1] : null;
        if (last?.maxdisk) {
          setDiskPct((last.disk / last.maxdisk) * 100);
          setDiskLabel(`${fmtBytes(last.disk)} of ${fmtBytes(last.maxdisk)}`);
        }
      })
      .catch(() => {});
    return () => { alive = false; };
  }, [data.serverId, graphable]);

  const memPct = data.live && data.live.maxMemBytes ? (data.live.memBytes / data.live.maxMemBytes) * 100 : null;
  const bwUsed = data.bandwidth.inBytes + data.bandwidth.outBytes;
  const bwAllow = data.bandwidth.allowanceTB * 1024 ** 4;
  const bwPct = bwAllow ? (bwUsed / bwAllow) * 100 : 0;

  const trends: Trend[] = [
