1975	    await notify(
1976	      server.userId,
1977	      `Snapshot ${op} (sandbox): ${name}`,
1978	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
1979	      `/dashboard/servers/${server.id}`
1980	    );
1981	    return;
1982	  }
1983	  const { conn } = await nodeFor(server);
1984	  let upid: string;
1985	  if (op === "create") {
1986	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
1987	  } else if (op === "delete") {
1988	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
1989	  } else {
1990	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
1991	  }
1992	  await conn.waitForTask(upid, 600_000);
