1995	    const current = await db.server.findUnique({ where: { id: server.id } });
1996	    if (current?.status === "RUNNING") {
1997	      try {
1998	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
