2022	              `[worker] snapshot rollback: could not resync guest password for server ${server.id} (vmid ${server.vmid})`
2023	            );
2024	          }
2025	        } else {
2026	          console.error(
2027	            `[worker] snapshot rollback: guest agent never answered for server ${server.id} (vmid ${server.vmid}) — password may now be stale`
2028	          );
2029	        }
2030	      }
2031	    }
2032	  }
