"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { resizeQuote, applyResize, ResizeError } from "./resize";
import { createResizeCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";
import { checkRateLimit } from "./rate-limit";
import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function queueJob(
  serverId: string,
  type:
    | "SNAPSHOT_CREATE"
    | "SNAPSHOT_DELETE"
    | "SNAPSHOT_ROLLBACK"
    | "BACKUP_CREATE"
    | "RESIZE"
    | "PASSWORD_RESET",
  payload?: Record<string, unknown>
): Promise<{ error?: string }> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };
  await db.job.create({ data: { type, serverId, payload: payload as any } });
  return {};
}

// ---------- Snapshots ----------

/**
 * The ONE snapshot-name normalisation, applied identically on every path.
 *
 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
 * this module accepts but the worker rejects is a job that reports QUEUED to the
 * customer and then dies in the worker with a message they never see. Delete and
 * rollback used to pass the raw argument straight through: a TypeScript parameter
 * type is not validation, and these are reachable with any string at all.
 */
function cleanSnapshotName(name: unknown): string {
  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
}

const SNAPSHOT_NAME_ERROR =
  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
  "Pick the snapshot from the list on the server page rather than typing its name.";

export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  const clean = cleanSnapshotName(name);
  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
  // A rollback rewinds the VM's disk. The worker can only do that against a real
  // VM in a steady state — the same precondition createSnapshot already enforced.
  // Without it we accepted the request, said nothing, and let the job fail in the
  // worker while the customer believed their server was being restored.
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to roll back to a snapshot." };
  }
  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name: clean });
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${clean}` } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

// ---------- Backups ----------

export async function createBackup(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped." };
  }
  const res = await queueJob(serverId, "BACKUP_CREATE");
  if (!res.error) {
    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
    revalidatePath(`/dashboard/servers/${serverId}`);
  }
  return res;
}

export type BackupJobStatus = {
  id: string;
  type: "BACKUP_CREATE" | "BACKUP_RESTORE";
  status: "QUEUED" | "RUNNING" | "DONE" | "FAILED";
  progress: number;
  step: string | null;
  error: string | null;
  createdAt: string;
};

/**
 * Return the most recent backup/restore job for a server so the UI can render a
 * live progress bar. Ownership-checked. Returns null if the server has never had
 * a backup/restore job. The client decides when to show the bar (in-flight) vs.
 * the completion/failure note.
 */
export async function getBackupJob(serverId: string): Promise<BackupJobStatus | null> {
  const { server } = await ownedServer(serverId);
  const job = await db.job.findFirst({
    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
    orderBy: { createdAt: "desc" },
    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
  });
  if (!job) return null;
  return {
    id: job.id,
    type: job.type as BackupJobStatus["type"],
    status: job.status as BackupJobStatus["status"],
    progress: job.progress,
    step: job.step,
    error: job.error,
    createdAt: job.createdAt.toISOString(),
  };
}

// ---------- Resize ----------

export async function resizeServer(
  serverId: string,
  planId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
  // the customer's name), so it carries the same impersonation guard as every
  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
  // This one was missed, which made "upgrade the plan" the one charge an admin
  // impersonating a customer could still put on that customer's balance.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
  // stopping a customer from spending LESS would be a gate with no one to
  // protect. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Validate + price the upgrade (ownership already checked above). resizeQuote
  // recomputes the exact prorated charge over the remaining term.
  let quote;
  try {
    quote = await resizeQuote(serverId, planId);
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    throw e;
  }
  const { newPlan, prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
  // the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card (not the full
  // proration). The confirm route credits the card amount to the wallet and then
  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
  // share and the card the rest — wallet never touched before the card clears.
  if (cardCents > 0) {
    const checkout = await createResizeCheckout(user, cardCents, {
      serverId,
      planId,
      planName: newPlan.name,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyResize({ serverId, planId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Root password reset ----------

export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reset its password." };
  }
  const res = await queueJob(serverId, "PASSWORD_RESET");
  if (!res.error) {
    await db.auditLog.create({
      data: { userId: user.id, action: "server.password_reset", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    revalidatePath(`/admin/servers/${serverId}`);
  }
  return res;
}

// ---------- Port forwarding (firewall/networking) ----------

import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
const MAX_FORWARDS_PER_SERVER = 10;

export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);
  const parsed = z
    .object({
      guestPort: z.coerce.number().int().min(1).max(65535),
      protocol: z.enum(["tcp", "udp"]),
    })
    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
  if (!parsed.success) return { error: "Invalid port." };

  const count = await db.portForward.count({ where: { serverId } });
  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };

  // Allocate the public port with the DB as the arbiter, not this read.
  //
  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
  // from a snapshot read and inserting it unguarded meant two requests that
  // overlapped — a double-click, or two customers adding a forward at the same
  // moment — both picked the same lowest free port and the loser's insert threw
  // a raw Prisma P2002. That exception escaped this action, so the customer got
  // a server-error page instead of a message, and (in production, where Next
  // redacts action errors) no clue what happened or that simply retrying works.
  //
  // Retry across the next few free candidates so an ordinary collision resolves
  // itself silently, and turn a genuine exhaustion into an honest, actionable
  // message rather than a crash.
  const used = new Set([
    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
  ]);
  const candidates: number[] = [];
  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
    if (!used.has(p)) candidates.push(p);
  }
  if (candidates.length === 0) {
    return {
      error:
        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
        "Delete a forward you no longer need, or contact support to have the pool widened.",
    };
  }

  let publicPort = 0;
  for (const candidate of candidates) {
    try {
      await db.portForward.create({
        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
      });
      publicPort = candidate;
      break;
    } catch (e: any) {
      // P2002 = another request took this port between our read and this insert.
      // Anything else is a real failure and must not be swallowed.
      if (e?.code !== "P2002") throw e;
    }
  }
  if (!publicPort) {
    return {
      error:
        "Another request took the public port we picked, several times in a row. " +
        "Nothing was created — please try adding the forward again.",
    };
  }

  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  // A NAT Minecraft server's game port isn't forwarded until this moment (see
  // worker/index.ts's provision() comment) — this may be the first time its
  // subdomain DNS has anything valid to point at.
  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deletePortForward(serverId: string, forwardId: string) {
  const { user } = await ownedServer(serverId);
  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
  // If this was the game's forward, the subdomain has nothing to point at anymore.
  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

/**
 * Rename a paid Minecraft server's `<subdomain>.play.nxeon.cloud`. Mirrors
 * lib/actions-free-minecraft.ts's changeFreeMinecraftSubdomain: format/reserved
 * check, then let the DB's unique constraint (Server.subdomain) catch the
 * same-table race rather than a separate findFirst-then-update (TOCTOU).
 */
export async function changeGameSubdomain(prev: unknown, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user, server } = await ownedServer(serverId);

  const rl = checkRateLimit(`game:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };

  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
  const formatError = validateSubdomainFormat(sub);
  if (formatError) return { error: formatError };
  if (sub === server.subdomain) return {};

  if (!(await isSubdomainAvailable(sub, { excludeServerId: serverId }))) {
    return { error: "That name is taken — try another." };
  }

  try {
    await db.server.update({ where: { id: serverId }, data: { subdomain: sub } });
  } catch (e: any) {
    if (e?.code === "P2002") return { error: "That name is taken — try another." };
    throw e;
  }

  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.game_subdomain_change", detail: `${serverId} -> ${sub}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import {
  planNatRules,
  reconcileNatChain,
  ruleSpec,
  type ForwardSource,
  type NatHost,
  type NatRule,
  type NatSyncResult,
} from "../lib/nat-rules";
import { agentEnsureChain, agentListChain, agentAddRule, agentDeleteRule, type AgentNode } from "../lib/node-agent";

const exec = promisify(execFile);

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChainLocal(chain: string) {
  try {
    await iptables(["-t", "nat", "-N", chain]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
  }
  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
  // issuance, migration remediation, backups, the Claude backfill — were hitting
  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
  // public IP is redirected; host-local :port traffic to anything else is
  // untouched, and the shared DNAT rules only match ports that actually forward.
  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
  if (publicIp) {
    try {
      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", chain]);
    } catch {
      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", chain]);
    }
  }
}

/**
 * The real, iptables-backed NatHost for the PRIMARY's own chain — the only
 * implementation production used before multi-node. The decision logic it is
 * handed to lives in lib/nat-rules.ts and is tested against an in-memory fake;
 * see the H5 incident note at the top of that file.
 */
function iptablesHost(chain: string): NatHost {
  return {
    ensureChain: () => ensureChainLocal(chain),
    listChain: async () => {
      const { stdout } = await exec("iptables", ["-t", "nat", "-S", chain]);
      return stdout;
    },
    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", chain, ...ruleSpec(r)]),
    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", chain, ...ruleSpec(r)]),
  };
}

/**
 * The remote, agent-backed NatHost for any non-primary node. Implements the
 * exact same NatHost seam over HTTPS — reconcileNatChain's tested
 * reconciliation logic runs unmodified against either implementation.
 */
function agentNatHost(node: AgentNode, chain: string): NatHost {
  return {
    ensureChain: () => agentEnsureChain(node, chain),
    listChain: () => agentListChain(node, chain),
    addRule: (r: NatRule) => agentAddRule(node, chain, r),
    deleteRule: (r: NatRule) => agentDeleteRule(node, chain, r),
  };
}

/** Dispatch: local iptables for the primary (the only node the worker itself
 *  runs on), the remote agent for everyone else. */
function natHostFor(node: { isPrimary: boolean } & AgentNode, chain: string): NatHost {
  return node.isPrimary ? iptablesHost(chain) : agentNatHost(node, chain);
}

/**
 * Reconcile every node's OWN NAT chain with the database, and verify each
 * result — one intent, one chain, one host PER NODE, never merged.
 *
 * Before multi-node this pulled every server platform-wide into a single
 * intent and always applied it to the local host's chain — harmless with one
 * node, but wrong the moment a second one exists: a node-2 server's forward
 * would be planned correctly and then installed on the PRIMARY's own
 * iptables, pointing at a private IP (10.20.1.x) the primary has no route to
 * — a rule that can never work, sitting in the wrong place. Servers are now
 * grouped by their own `nodeId` (falling back to the primary for the rare
 * legacy row with none, matching worker/index.ts's `nodeFor()` fallback) and
 * each node's chain is reconciled independently against ITS OWN NatHost.
 *
 * Every node listed in the `Node` table is attempted — not just `enabled`
 * ones — because disabling a node only stops NEW placement there; a server
 * already running on a disabled/draining node still needs its forwarding
 * kept correct. A node whose agent isn't reachable (or has no token
 * configured yet) fails independently and is reported, never silently
 * skipped and never able to abort another node's sync — the same H5 lesson
 * ("one failure must not cascade") applied one level up.
 */
export async function syncPortForwards(): Promise<NatSyncResult[]> {
  const [nodes, servers] = await Promise.all([
    db.node.findMany(),
    db.server.findMany({
      where: {
        ipAddress: { not: null },
        sshPort: { not: null },
        status: { notIn: ["SUSPENDED", "DELETING"] },
      },
      include: { portForwards: true },
    }),
  ]);

  const primary = nodes.find((n) => n.isPrimary);
  const byNode = new Map<string, typeof servers>();
  for (const s of servers) {
    const nodeId = (s as { nodeId?: string | null }).nodeId ?? primary?.id;
    if (!nodeId) continue; // no node row at all yet (fresh DB) — nothing to reconcile against
    if (!byNode.has(nodeId)) byNode.set(nodeId, []);
    byNode.get(nodeId)!.push(s);
  }

  const results: NatSyncResult[] = [];
  const errors: string[] = [];

  for (const node of nodes) {
    const nodeServers = byNode.get(node.id) ?? [];
    const intent = planNatRules(nodeServers as unknown as ForwardSource[]);

    // Two data problems that used to be invisible because the old loop just
    // built whatever it was handed. Neither blocks this node's sync — the
    // ruleset installed is still verified end to end — but neither is
    // swallowed either.
    for (const c of intent.conflicts) {
      console.error(
        `[nat] ${node.name}: port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
          `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
      );
    }
    for (const r of intent.rejected) {
      console.error(`[nat] ${node.name}/${r.hostname}: no rule installed — ${r.reason}`);
    }

    try {
      const result = await reconcileNatChain(natHostFor(node, node.natChain), node.natChain, intent);
      if (result.unparsed.length) {
        console.warn(
          `[nat] ${node.name}/${node.natChain} contains ${result.unparsed.length} rule(s) this engine did ` +
            `not write and will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
        );
      }
      console.log(
        `[nat] ${node.name}/${node.natChain} verified: ${result.verified} rule(s) present ` +
          `(+${result.added} / -${result.deleted})`
      );
      results.push(result);
    } catch (e: any) {
      // Collected, not thrown immediately — one node's failure (agent
      // unreachable, no token configured, a genuinely broken ruleset) must
      // never prevent every OTHER node's sync from being attempted.
      const msg = `${node.name}/${node.natChain}: ${String(e?.message ?? e)}`;
      console.error(`[nat] sync FAILED for ${msg}`);
      errors.push(msg);
    }
  }

  if (errors.length) {
    throw new Error(`NAT sync failed for ${errors.length} node(s): ${errors.join(" | ")}`);
  }
  return results;
}

/**
 * For callers that must not be re-queued by a sync failure (server DELETE runs
 * this after the row is gone, so a throw dies on "Server not found" on retry and
 * the sync is never re-attempted — H5's aggravating factor).
 *
 * It still never claims success: the failure is logged in full and returned, so
 * the caller can surface it. What it will not do is convert a networking problem
 * into a stuck job that hides it.
 */
export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
  try {
    await syncPortForwards();
    return null;
  } catch (e: any) {
    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
    return e instanceof Error ? e : new Error(String(e));
  }
}

"use client";

import type { ReactNode } from "react";
import { Icon } from "@/components/nx/Icon";
import { CopyLine } from "./CopyLine";
import { Card, Row, SubNav, Hint, TAG, type SubSection } from "./ui";

/**
 * Networking, on the side-rail arrangement.
 *
 * Four named sections rather than six stacked cards down one column: where this
 * machine answers, who may log in, what is exposed, and who may reach it. The
 * previous pass put all four in a single scroll of full-width slabs.
 *
 * Nothing here invents a value. A NAT server genuinely has a private address
 * and forwarded ports; a dedicated-IP server has neither, so it is offered a
 * different set of sections rather than the same set full of dashes.
 */

/* `action` is a rendered node, not a callback. This panel is a client
   component and the page that fills it is a server component — a function prop
   cannot cross that boundary, and passing one crashed the tab. */
type Forward = {
  id: string; publicPort: number; guestPort: number; protocol: string;
  managed?: boolean; action?: ReactNode;
};
type Rule = {
  id: string; action: string; protocol: string; portLabel: string;
  sourceCidr: string; comment: string | null; enabled: boolean;
  manage?: ReactNode;
};

type Key = "addresses" | "access" | "forwards" | "firewall";

export function VpsNetworkingPanel({
  dedicated, publicIp, privateIp, ipv6, sshPort,
  forwards, rules,
  credentials, firewallPresets, addForwardForm, addRuleForm,
}: {
  dedicated: boolean;
  publicIp: string | null;
  privateIp: string | null;
  ipv6: string | null;
  sshPort: number | null;
  forwards: Forward[];
  rules: Rule[];
  credentials: ReactNode;
  firewallPresets: ReactNode;
  addForwardForm: ReactNode;
  addRuleForm: ReactNode;
}) {
  const sections: SubSection<Key>[] = [
    { key: "addresses", label: "Addresses", sub: "Where it answers", icon: "globe2" },
    { key: "access", label: "Root access", sub: "Password and SFTP", icon: "key" },
    ...(dedicated ? [] : [{ key: "forwards" as Key, label: "Port forwards", sub: "What is exposed", icon: "transfer" }]),
    { key: "firewall", label: "Firewall", sub: "Who may reach it", icon: "shield2" },
  ];

  const custom = forwards.filter((f) => !f.managed);

  return (
    <SubNav
      sections={sections}
      slots={{
        addresses: (
          <Card title="Addresses">
            <Hint>
              {dedicated
                ? "This server owns a public IP outright. Every port is reachable directly on it, with no forwarding in the way."
                : "This server sits behind NAT. It has a private address inside our network and reaches the outside world through forwarded ports on the shared public IP."}
            </Hint>
            <div className="flex flex-wrap gap-2">
              {publicIp && <CopyLine label={dedicated ? "Public IP" : "Shared public IP"} value={publicIp} />}
              {!dedicated && privateIp && <CopyLine label="Private IP" value={privateIp} />}
              {ipv6 && <CopyLine label="IPv6" value={ipv6} />}
              {/* No SSH command chip: the hero pins it to every tab, and Root
                  access carries the SFTP one. */}
              {!dedicated && sshPort && <CopyLine label="SSH port" value={String(sshPort)} />}
            </div>
            {!dedicated && (
              <p className="mt-3 text-[11.5px] leading-relaxed text-tx-faint">
                To reach a service you have forwarded, connect to{" "}
                <span className="mono text-tx-dim">{publicIp}:&lt;public port&gt;</span> — not the private
                address, which is only routable inside our network.
              </p>
            )}
          </Card>
        ),

        access: credentials,

        forwards: (
          <Card title="Port forwards" action={firewallPresets}>
            <Hint>
              Each forward maps a public port on the shared IP to a port inside your server. A free
              public port is assigned automatically; up to ten per server.
            </Hint>
            <ul className="flex flex-col">
              {forwards.map((f) => (
                <Row key={f.id}>
                  <span className="mono text-[12.5px] text-tx">{publicIp}:{f.publicPort}</span>
                  <Icon name="transfer" size={13} className="text-tx-faint" />
                  <span className="mono text-[12.5px] text-tx-dim">port {f.guestPort}</span>
                  <span className={`${TAG} border-rim-hi text-tx-dim`}>{f.protocol}</span>
                  <span className="ml-auto flex items-center gap-2">
                    {f.managed
                      ? <span className={`${TAG} border-sky-400/35 text-sky-300`}>Managed</span>
                      : f.action}
                  </span>
                </Row>
              ))}
            </ul>
            {custom.length === 0 && (
              <p className="mt-3 text-[12.5px] text-tx-faint">
                Only the managed SSH forward exists. Add one below to expose a web server or any other
                service.
              </p>
            )}
            <div className="mt-4 border-t border-rim-soft pt-4">{addForwardForm}</div>
          </Card>
        ),

        firewall: (
          <Card title="Inbound firewall">
            <Hint>
              Which sources may reach ports inside your server. Rules apply top to bottom, first match
              wins, and take effect within a minute. SSH stays reachable whatever the rules say, so you
              cannot lock yourself out.
            </Hint>
            {rules.length === 0 ? (
              <p className="text-[12.5px] leading-relaxed text-tx-faint">
                No rules yet, so inbound traffic to forwarded ports is unrestricted. Add an{" "}
                <span className="font-bold text-tx-dim">Allow</span> rule to narrow that to the sources
                you trust.
              </p>
            ) : (
              <ul className="flex flex-col">
                {rules.map((r) => (
                  <Row key={r.id} dim={!r.enabled}>
                    <span className={`${TAG} ` + (r.action === "ALLOW"
                      ? "border-emerald-400/35 text-emerald-300"
                      : "border-rose-400/35 text-rose-300")}>
                      {r.action === "ALLOW" ? "Allow" : "Deny"}
                    </span>
                    <span className="mono text-[12.5px] text-tx">{r.portLabel}</span>
                    <span className={`${TAG} border-rim-hi text-tx-dim`}>{r.protocol}</span>
                    <span className="mono text-[12px] text-tx-dim">from {r.sourceCidr}</span>
                    {r.comment && <span className="truncate text-[12px] text-tx-faint">{r.comment}</span>}
                    <span className="ml-auto flex items-center gap-2">
                      {!r.enabled && <span className={`${TAG} border-amber-400/35 text-amber-300`}>Off</span>}
                      {r.manage}
                    </span>
                  </Row>
                ))}
              </ul>
            )}
            <div className="mt-4 border-t border-rim-soft pt-4">{addRuleForm}</div>
          </Card>
        ),
      }}
    />
  );
}

import { db } from "../lib/db";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { withServerSsh, exec as sshExecOn } from "../lib/ssh-exec";
import { SANDBOX } from "../lib/sandbox";
import { validateRule, buildReconcileScript, FW_CHAIN, type ValidatedRule } from "../lib/firewall-rules";
import type { Job } from "@prisma/client";

const CMD_TIMEOUT_MS = 60_000;

/**
 * Apply a customer's inbound firewall to their guest, idempotently.
 *
 * MECHANISM: guest-side iptables over SSH, via the same connectionTarget()-based
 * plumbing (lib/ssh-exec.ts's withServerSsh/exec) every other control-panel
 * feature uses — host/port resolve to the server's dedicated IP, or its OWN
 * node's public IP + NAT-forwarded sshPort, never a hardcoded/private address.
 * The Proxmox per-VM firewall API was the alternative, but lib/proxmox.ts
 * exposes only a generic REST client with no firewall helper, and enabling it
 * requires flipping cluster/node/NIC firewall flags that interact with the
 * existing NAT model — a far larger, riskier change for guests that are already
 * reachable as root over SSH. So: guest iptables.
 *
 * SAFETY: the reconcile SCRIPT is built by lib/firewall-rules.ts from VALIDATED,
 * structured fields only. Each DB row is re-run through `validateRule` here
 * (defence in depth) before it can contribute a line; a row that fails is skipped
 * and logged, never interpolated. Ports are integers, protocol/action are closed
 * enums, and the source CIDR is regex-validated + normalised — so no raw customer
 * string (the free-text `comment` least of all) ever reaches the guest shell.
 *
 * IDEMPOTENT: the script creates the NXEON_FW chain once, ensures INPUT jumps to
 * it once, then FLUSHES only that chain and rebuilds it — so re-running yields
 * identical kernel state and never accumulates stale rules or touches the
 * customer's own INPUT rules.
 *
 * ANTI-LOCKOUT: the baseline always accepts loopback, ESTABLISHED/RELATED and
 * tcp/22, so SSH stays reachable no matter what the customer configures, and the
 * default DROP is appended only when they have at least one ALLOW rule.
 */
export async function syncFirewall(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("syncFirewall: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: {
      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
      dedicatedIp: true,
      node: true,
    },
  });
  if (!server) {
    // Row is gone (server deleted); the cascade removed its rules too. Nothing to do.
    console.log(`[fw] server ${serverId} not found — skipping firewall sync`);
    return;
  }

  // Don't fight the lifecycle: a suspended/deleting/not-yet-provisioned VM has no
  // reachable guest to configure. The rules stay in the DB and re-apply on the
  // next sync once the server is steady again.
  if (["SUSPENDED", "DELETING", "PENDING", "PROVISIONING", "REINSTALLING", "STOPPED", "ERROR"].includes(server.status)) {
    console.log(`[fw] server ${serverId} status=${server.status} — deferring firewall sync`);
    return;
  }

  // Re-validate every ENABLED row through the SAME gate the action used. A row
  // that somehow got into the DB malformed is dropped from the applied set (and
  // reported) rather than allowed to break the build.
  const validated: ValidatedRule[] = [];
  for (const r of server.firewallRules) {
    if (!r.enabled) continue;
    const result = validateRule({
      action: r.action,
      protocol: r.protocol,
      portFrom: r.portFrom,
      portTo: r.portTo,
      sourceCidr: r.sourceCidr,
    });
    if (!result.ok) {
      console.error(`[fw] server ${serverId} rule ${r.id} rejected at apply: ${result.error}`);
      continue;
    }
    validated.push(result.rule);
  }

  const script = buildReconcileScript(validated);

  if (SANDBOX) {
    console.log(`[fw] SANDBOX — would apply ${validated.length} rule(s) to ${server.hostname}:\n${script}`);
    return;
  }

  const password = serverRootPassword(server);
  if (!connectionTarget(server) || !password) {
    throw new Error(`syncFirewall: server ${serverId} has no reachable IP or root password`);
  }

  // The script travels as a single-quoted payload to `bash -c` on the guest;
  // nothing here is assembled by a host shell.
  const wrapped = `bash -c ${shSingleQuote(script)}`;

  try {
    const r = await withServerSsh(server, (conn) => sshExecOn(conn, wrapped, CMD_TIMEOUT_MS));
    if (r.code !== 0) {
      const out = `${r.stdout}${r.stderr ? `\n${r.stderr}` : ""}`.trim();
      throw new Error(
        `syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — exit ${r.code ?? "?"}` +
          (out ? `: ${out.slice(0, 400)}` : "")
      );
    }
  } catch (e: any) {
    if (e instanceof Error && e.message.startsWith("syncFirewall:")) throw e;
    // Connection-level failure (timeout, unreachable, no password) — exec()
    // itself threw rather than returning a non-zero exit.
    throw new Error(`syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — ${e?.message ?? e}`);
  }

  console.log(`[fw] applied ${validated.length} rule(s) to ${server.hostname} (${FW_CHAIN})`);
}

/** Single-quote a payload for a POSIX shell (`'` → `'\''`). */
function shSingleQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { validateRule } from "./firewall-rules";
import type { FirewallAction, FirewallProtocol } from "@prisma/client";

/**
 * Inbound firewall (security-group) rules for a customer's VPS.
 *
 * Ownership is enforced exactly like the port-forward actions: `ownedServer`
 * throws unless the caller owns the server (or is an admin). Every mutable field
 * is validated + normalised by lib/firewall-rules.ts BEFORE it is persisted, and
 * again in the worker before it reaches a shell. Each change enqueues a
 * SYNC_FIREWALL job that re-applies the FULL rule set idempotently on the guest.
 */

const MAX_RULES_PER_SERVER = 50;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function enqueueSync(serverId: string) {
  await db.job.create({ data: { type: "SYNC_FIREWALL", serverId } });
}

export async function listFirewallRules(serverId: string) {
  await ownedServer(serverId);
  return db.firewallRule.findMany({
    where: { serverId },
    orderBy: [{ position: "asc" }, { createdAt: "asc" }],
  });
}

export async function addFirewallRule(prev: any, formData: FormData): Promise<{ error?: string }> {
  const serverId = String(formData.get("serverId") ?? "");
  const { user } = await ownedServer(serverId);

  // VALIDATE everything before it is persisted. `validateRule` is the same gate
  // the worker uses, so a rule this action accepts is guaranteed buildable.
  const result = validateRule({
    action: formData.get("action"),
    protocol: formData.get("protocol"),
    portFrom: formData.get("portFrom"),
    portTo: formData.get("portTo"),
    sourceCidr: formData.get("sourceCidr"),
  });
  if (!result.ok) return { error: result.error };

  // `comment` is customer free text — persisted + shown, NEVER shell-bound.
  const comment = String(formData.get("comment") ?? "").trim().slice(0, 200) || null;

  const count = await db.firewallRule.count({ where: { serverId } });
  if (count >= MAX_RULES_PER_SERVER) {
    return { error: `Limit of ${MAX_RULES_PER_SERVER} firewall rules reached. Delete one first.` };
  }

  const last = await db.firewallRule.findFirst({
    where: { serverId },
    orderBy: { position: "desc" },
    select: { position: true },
  });
  const position = (last?.position ?? -1) + 1;

  const { action, protocol, portFrom, portTo, sourceCidr } = result.rule;
  await db.firewallRule.create({
    data: {
      serverId,
      direction: "INBOUND",
      action: action as FirewallAction,
      protocol: protocol as FirewallProtocol,
      portFrom,
      portTo,
      sourceCidr,
      comment,
      enabled: true,
      position,
    },
  });

  await enqueueSync(serverId);
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.firewall_add",
      detail: `${serverId} ${action} ${protocol} ${portFrom ?? "*"}-${portTo ?? "*"} from ${sourceCidr}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function toggleFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  const rule = await db.firewallRule.findFirst({ where: { id: ruleId, serverId } });
  if (!rule) return { error: "Rule not found." };
  await db.firewallRule.update({ where: { id: rule.id }, data: { enabled: !rule.enabled } });
  await enqueueSync(serverId);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.firewall_toggle", detail: `${serverId} ${ruleId} -> ${!rule.enabled}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

export async function deleteFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  await db.firewallRule.deleteMany({ where: { id: ruleId, serverId } });
  await enqueueSync(serverId);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.firewall_delete", detail: `${serverId} ${ruleId}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

/**
 * Reorder rules by an explicit list of rule ids (new first-match order). Only
 * ids that actually belong to the server are moved; anything else is ignored, so
 * a caller cannot reposition another tenant's rule.
 */
export async function reorderFirewallRules(serverId: string, orderedIds: string[]): Promise<{ error?: string }> {
  const { user } = await ownedServer(serverId);
  if (!Array.isArray(orderedIds) || orderedIds.length === 0) return { error: "Nothing to reorder." };

  const owned = await db.firewallRule.findMany({ where: { serverId }, select: { id: true } });
