334	        type: "RESIZE",
335	        serverId,
336	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
337	      },
338	    }),
339	    db.auditLog.create({
340	      data: {
341	        userId: user.id,
342	        action: "server.resize_down",
343	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
344	      },
345	    }),
346	  ]);
347	
348	  revalidatePath(`/dashboard/servers/${serverId}`);
349	  return {};
350	}
351	
352	// ---------- 4. Self-serve cancel / terminate (+ prorated refund) ----------
353	
354	/**
355	 * Customer-initiated cancellation of a VPS / game server. Two modes:
356	 *
357	 *   • "period_end"  — stop auto-renew and keep the server running until `expiresAt`.
358	 *                     No money moves; the paid term is honoured to its end. Default
359	 *                     and always-safe choice.
360	 *   • "immediate"   — terminate NOW: enqueue the SAME audited DELETE job the manual
361	 *                     delete uses (worker destroys the VM), and — for a standard VPS
362	 *                     with unused paid time — credit the prorated refund to the WALLET
363	 *                     (never a Stripe refund; safer and reversible) in the same
364	 *                     transaction, with a ledger line and a credit-note invoice.
365	 *
366	 * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
367	 * can move money — an admin must not do either on a customer's behalf). Respects the
368	 * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
369	 * warning and the refund figure.
370	 */
371	export async function cancelService(
372	  serverId: string,
373	  mode: "immediate" | "period_end",
374	): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
375	  // Moves money and destroys a resource — never while impersonating.
376	  await assertNotImpersonating();
377	  const { user, server } = await ownedServer(serverId);
378	
379	  if (server.status === "DELETING") return { error: "This server is already being cancelled." };
380	
381	  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
382	  if (mode === "period_end") {
383	    if (server.isFree || !server.expiresAt) {
384	      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
385	    }
386	    if (!server.autoRenew) {
387	      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
388	    }
389	    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
390	    await db.auditLog.create({
391	      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
392	    });
393	    revalidatePath(`/dashboard/servers/${serverId}`);
394	    return {
395	      ok: true,
396	      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
397	    };
398	  }
399	
400	  // ---- Immediate termination (+ prorated wallet refund). ----
401	  if (await hasInflightJob(serverId)) {
402	    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
403	  }
404	
405	  const refundCents = terminationRefundCents({
406	    isFree: server.isFree,
407	    expiresAt: server.expiresAt,
408	    isGame: !!server.gamePlanId,
409	    planMonthlyCents: server.plan.priceCents,
410	    termMonths: server.termMonths,
411	    termPromoPercent: server.termPromoPercent,
412	    // Authoritative refund basis: the real plan cash collected for the term, net of
413	    // promo AND coupon. Null on legacy rows → the helper falls back to the (safe,
414	    // never-over-refunding) termPromoPercent formula.
415	    refundableTermCents: server.refundableTermCents,
416	    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
417	  });
418	
419	  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
420	  // to DELETING only if it is not already DELETING. A double-click / retry that loses
421	  // the race (`adv.count === 0`) does NOTHING — no second refund, no second DELETE job.
422	  // Only the winner issues the refund credit + ledger line + credit-note + DELETE job,
423	  // so refund and termination commit together and can never both run twice. (The old
424	  // array form flipped status unconditionally, so N concurrent calls all refunded.)
425	  const won = await db.$transaction(async (tx) => {
426	    const adv = await tx.server.updateMany({
427	      where: { id: server.id, status: { not: "DELETING" } },
428	      data: { status: "DELETING", autoRenew: false },
429	    });
430	    if (adv.count !== 1) return false; // lost the race — another call already claimed it
431	
432	    if (refundCents > 0) {
433	      await tx.user.update({
434	        where: { id: server.userId },
435	        data: { balanceCents: { increment: refundCents } },
436	      });
437	      await tx.walletTransaction.create({
438	        data: {
439	          userId: server.userId,
440	          amountCents: refundCents,
441	          description: `Cancellation refund (unused term) — ${server.hostname}`,
442	        },
443	      });
444	      // A credit-note invoice for the refund, so the ledger line has a matching
445	      // billing document the customer can download. Marked REFUNDED.
446	      await tx.invoice.create({
447	        data: invoiceCreateData({
448	          userId: server.userId,
449	          description: `Cancellation refund — ${server.hostname}`,
450	          status: "REFUNDED",
451	          lineItems: [
452	            {
453	              description: `Prorated refund for unused term — ${server.hostname}`,
454	              qty: 1,
455	              unitCents: refundCents,
456	              amountCents: refundCents,
457	            },
458	          ],
459	        }),
460	      });
461	    }
462	    await tx.job.create({ data: { type: "DELETE", serverId } });
463	    await tx.auditLog.create({
464	      data: {
465	        userId: user.id,
466	        action: "server.cancel_immediate",
467	        detail: `${serverId} refund=${refundCents}`,
468	      },
469	    });
470	    return true;
471	  });
472	
473	  if (!won) {
474	    return { error: "This server is already being cancelled." };
475	  }
476	
477	  if (refundCents > 0) {
478	    await db.notification
479	      .create({
480	        data: {
481	          userId: server.userId,
482	          title: `Refund of $${(refundCents / 100).toFixed(2)} credited to your wallet`,
483	          body: `We refunded the unused portion of ${server.hostname}'s term as wallet credit. Your data on this server is being erased and cannot be recovered.`,
484	          href: "/dashboard/billing",
485	        },
486	      })
487	      .catch(() => {});
488	  }
489	
490	  revalidatePath(`/dashboard/servers/${serverId}`);
491	  return {
492	    ok: true,
493	    refundCents,
494	    message:
495	      refundCents > 0
496	        ? `Server termination started. $${(refundCents / 100).toFixed(2)} for the unused part of your term has been credited to your wallet. All data on this server is being permanently erased.`
497	        : `Server termination started. All data on this server is being permanently erased.`,
498	  };
499	}
500	
501	// ---------- Retention offer (STAY50) ----------
502	//
503	// Shown as an interstitial the instant a customer clicks EITHER cancel path
504	// above ("Turn off auto-renew" / "Terminate now") in CancelService.tsx, BEFORE
505	// `cancelService` itself ever runs — "Wait — here's 50% off your next
506	// renewal. Stay and save?" with a real, undeceptive choice: accept it (this
507	// module), or continue with the cancellation exactly as today.
508	//
509	// THIS IS NOT THE SAME MECHANISM AS THE CHECKOUT COUPON PATH
510	// (lib/order.ts / lib/coupon-order.ts). There is no new order here for that
511	// code to fire on — the discount has to land on a FUTURE RENEWAL CHARGE
512	// against an EXISTING server, so it rides `Server.pendingRenewalDiscountPercent`
513	// (see that field's doc comment in prisma/schema.prisma and
514	// `PricedServer.pendingRenewalDiscountPercent` in lib/renewal-charge.ts for how
515	// `renewalCharge` reads and the worker/`renewNow` clear it). The real Coupon /
516	// CouponRedemption engine is still reused here, but ONLY for what it is
517	// already good at: proving "has this account ever redeemed STAY50 before" —
518	// the exact same `@@unique([couponId, userId])` constraint that makes every
519	// other one-per-person coupon on this platform enforceable, applied here as a
520	// simple atomic claim rather than a checkout-time price adjustment.
521	const RETENTION_COUPON_CODE = "STAY50";
522	const RETENTION_DISCOUNT_PERCENT = 50;
523	
524	/**
525	 * Has this ACCOUNT already spent its one lifetime "stay and save" offer?
526	 *
527	 * Scoped to the ACCOUNT, not the server that triggered it: the coupon engine's
528	 * uniqueness is `(couponId, userId)`, not `(couponId, userId, serverId)` — there
529	 * is no server dimension to redeem against. So redeeming STAY50 while cancelling
530	 * one server spends the account's only redemption; cancelling a DIFFERENT
531	 * server later does not offer it again. This is a deliberate choice, not a
532	 * limitation of the schema: without it, a customer with three servers could
533	 * cancel-then-restore each one in turn and collect three separate 50%-off
534	 * renewals from what is supposed to be a single save-the-account nudge. One
535	 * offer per account, ever, mirrors how every other first-time/one-per-person
536	 * coupon on this platform already works.
537	 */
538	async function hasRetentionOfferAvailable(userId: string): Promise<{ coupon: { id: string; active: boolean; maxRedemptions: number | null; timesRedeemed: number } } | null> {
539	  const coupon = await db.coupon.findUnique({
540	    where: { code: RETENTION_COUPON_CODE },
541	    select: { id: true, active: true, maxRedemptions: true, timesRedeemed: true },
542	  });
543	  if (!coupon || !coupon.active) return null;
544	  const used = await db.couponRedemption.findUnique({
545	    where: { couponId_userId: { couponId: coupon.id, userId } },
546	    select: { id: true },
547	  });
548	  if (used) return null;
549	  return { coupon };
550	}
551	
552	/**
553	 * Server-side eligibility check for the cancel-flow interstitial — read by the
554	 * server component that renders `CancelService` so the "stay and save" popup
555	 * is only ever offered when it could actually do something: the master
556	 * setting is on, this server has a real billing term to discount, it doesn't
557	 * already carry a pending discount, and this account hasn't used STAY50
558	 * before. Never trust a client-only version of this check for something that
559	 * decides whether a real discount can be claimed.
560	 */
561	export async function retentionOfferEligible(serverId: string): Promise<boolean> {
562	  const { user, server } = await ownedServer(serverId);
563	  if (!(await getSettingBool("retention_offer_enabled", true))) return false;
564	  if (server.isFree || !server.expiresAt) return false;
565	  if (server.pendingRenewalDiscountPercent != null) return false;
566	  return (await hasRetentionOfferAvailable(user.id)) !== null;
567	}
568	
569	/**
570	 * Accept the retention offer: claim STAY50 (one per account, ever) and stamp
571	 * the discount onto THIS server for its very next renewal only.
572	 *
573	 * Deliberately does NOT itself cancel, un-cancel or terminate anything beyond
574	 * turning auto-renew back on (accepting the offer is, definitionally, a
575	 * decision to keep renewing) — the caller (CancelService.tsx) is responsible
576	 * for not proceeding with whichever cancellation the customer was about to
577	 * make. That keeps this function's blast radius exactly "one server's next
578	 * bill", the same discipline `claimOrderCoupon` keeps for a checkout coupon.
579	 */
580	export async function claimRetentionOffer(serverId: string): Promise<{ error?: string; ok?: boolean }> {
581	  await assertNotImpersonating();
582	  const { user, server } = await ownedServer(serverId);
583	
584	  if (!(await getSettingBool("retention_offer_enabled", true))) {
585	    return { error: "This offer isn't available right now." };
586	  }
587	  if (server.isFree || !server.expiresAt) {
588	    return { error: "This server has no billing term to discount." };
589	  }
590	  if (server.pendingRenewalDiscountPercent != null) {
591	    return { error: "A discount is already pending on this server's next renewal." };
592	  }
593	
594	  const available = await hasRetentionOfferAvailable(user.id);
595	  if (!available) {
596	    return { error: "You've already used this offer, or it isn't available right now." };
597	  }
598	  const { coupon } = available;
599	
600	  try {
601	    await db.$transaction(async (tx) => {
602	      // Same atomic-claim shape as claimOrderCoupon (lib/order.ts): a conditional
603	      // increment on the coupon's own counter, then the unique-constrained
604	      // insert. Two concurrent claims (two tabs) can't both win — the loser's
605	      // insert throws P2002 and rolls the increment back with it.
606	      const claim = await tx.coupon.updateMany({
607	        where:
608	          coupon.maxRedemptions === null
609	            ? { id: coupon.id, active: true }
610	            : { id: coupon.id, active: true, timesRedeemed: { lt: coupon.maxRedemptions } },
611	        data: { timesRedeemed: { increment: 1 } },
612	      });
613	      if (claim.count !== 1) throw new Error("RETENTION_OFFER_EXHAUSTED");
614	      try {
615	        await tx.couponRedemption.create({
616	          data: { couponId: coupon.id, userId: user.id, amountCents: 0, context: "retention" },
617	        });
618	      } catch {
619	        // Unique violation on (coupon, user): already claimed, most likely a
620	        // race with another tab. Throwing rolls back the increment above.
621	        throw new Error("RETENTION_OFFER_ALREADY_USED");
622	      }
623	      await tx.server.update({
624	        where: { id: server.id },
625	        data: { pendingRenewalDiscountPercent: RETENTION_DISCOUNT_PERCENT, autoRenew: true },
626	      });
627	      await tx.auditLog.create({
628	        data: { userId: user.id, action: "server.retention_offer_claimed", detail: serverId },
629	      });
630	    });
631	  } catch (e) {
632	    if (e instanceof Error && e.message === "RETENTION_OFFER_ALREADY_USED") {
633	      return { error: "You've already used this offer once." };
634	    }
635	    if (e instanceof Error && e.message === "RETENTION_OFFER_EXHAUSTED") {
636	      return { error: "This offer is no longer available." };
637	    }
638	    throw e;
639	  }
640	
641	  revalidatePath(`/dashboard/servers/${serverId}`);
642	  return { ok: true };
643	}
