"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { diskExpandQuote, applyDiskExpand, DiskExpandError } from "./disk-expand";
import { createDiskExpandCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { normalizeExtraDiskGB } from "./extra-disk";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Add storage": grow ONE server's own root disk by N GB without
 * changing its plan (CPU/RAM/plan price are untouched).
 *
 * Money path is a carbon copy of lib/actions-server.ts resizeServer:
 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
 * The wallet is only ever debited by applyDiskExpand, and only after the card
 * portion has cleared, so displayed === charged and nothing is charged twice.
 *
 * GROWTH IS ONE-WAY. There is deliberately no companion "shrink" action.
 */

/** Max expansions a single customer may start in RATE_WINDOW_MS. */
const MAX_EXPANDS_PER_WINDOW = 5;
const RATE_WINDOW_MS = 10 * 60_000;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function expandServerDisk(
  serverId: string,
  addGB: number,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: a disk expansion is an irreversible charge.
  // See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Round DOWN to a purchasable amount — a malformed value can only ever cost
  // the customer less, never more (see normalizeExtraDiskGB).
  const gb = normalizeExtraDiskGB(addGB);
  if (gb <= 0) return { error: "Choose an amount of storage to add." };

  // Rate limit: expansions are irreversible and each one queues real hypervisor
  // work, so cap how fast a single account can fire them off.
  const recent = await db.job.count({
    where: {
      type: "DISK_EXPAND",
      createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) },
      server: { userId: user.id },
    },
  });
  if (recent >= MAX_EXPANDS_PER_WINDOW) {
    return { error: "Too many storage expansions just now — please wait a few minutes and try again." };
  }

  // Reject while another job is in flight, and only from a steady run state.
  // (applyDiskExpand re-checks both; this returns the friendlier message first.)
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to add storage." };
  }
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  // Validate + price the expansion (ownership already checked above).
  let quote;
  try {
    quote = await diskExpandQuote(serverId, gb);
  } catch (e) {
    if (e instanceof DiskExpandError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy/resize flows. AddStorage
  // computes the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card. The confirm route
  // credits the card amount to the wallet and then debits the FULL proration
  // (encoded as chargeCents), so the wallet absorbs its share and the card the
  // rest — the wallet is never touched before the card clears.
  if (cardCents > 0) {
    const checkout = await createDiskExpandCheckout(user, cardCents, {
      serverId,
      addGB: gb,
      hostname: server.hostname,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyDiskExpand({ serverId, addGB: gb, actorUserId: user.id });
  } catch (e) {
    if (e instanceof DiskExpandError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { dedicatedIpPurchaseQuote, applyDedicatedIpPurchase, DedicatedIpPurchaseError } from "./dedicated-ip-purchase";
import { createDedicatedIpCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Add dedicated IP": give an ALREADY-provisioned server (VPS or
 * game) its own dedicated public IPv4, for a server that doesn't already have
 * one. Money path is a carbon copy of lib/actions-disk.ts expandServerDisk:
 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
 * The wallet is only ever debited by applyDedicatedIpPurchase, and only after
 * the card portion has cleared, so displayed === charged and nothing is
 * charged twice. The actual IP claim + network reconfiguration happens
 * asynchronously in the worker (ASSIGN_DEDICATED_IP) — see
 * lib/dedicated-ip-purchase.ts's header for why that split is deliberate.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function purchaseDedicatedIp(
  serverId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating — same
  // guard as every other money movement on a server (resizeServer,
  // expandServerDisk).
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: this is an irreversible real-infra charge. See
  // lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  if (server.dedicatedIp) return { error: "This server already has a dedicated IP." };

  // Reject while another job is in flight, and only from a steady run state.
  // (applyDedicatedIpPurchase re-checks both; this returns the friendlier
  // message first.)
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to add a dedicated IP." };
  }
  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  let quote;
  try {
    quote = await dedicatedIpPurchaseQuote(serverId);
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the resize/disk-expand flows.
  // AddDedicatedIp computes the same split (lib/wallet-split.ts) so
  // displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  if (cardCents > 0) {
    const checkout = await createDedicatedIpCheckout(user, cardCents, {
      serverId,
      hostname: server.hostname,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `A dedicated IP costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  try {
    await applyDedicatedIpPurchase({ serverId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- Self-service backup restore ----------

export type ServerBackup = { volid: string; ctime?: number; size?: number };

/**
 * List the vzdump backups on the `backup` storage that belong to this server's
 * VMID. Read-only Proxmox call, ownership-checked.
 */
export async function listServerBackups(
  serverId: string
): Promise<{ error?: string; backups?: ServerBackup[] }> {
  const { server } = await ownedServer(serverId);
  if (!server.vmid) return { backups: [] };
  try {
    const backups = await listBackupsForServer(server);
    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
    return { backups };
  } catch {
    return { error: "Could not reach the hypervisor — try again in a moment." };
  }
}

/**
 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
 * the server's current disk. The volid is validated against the server's own
 * backups so a customer can only restore their own VM's archives.
 */
export async function requestRestore(
  serverId: string,
  volid: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!server.vmid) return { error: "Server has no VM yet." };
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to restore a backup." };
  }

  // Validate the archive actually belongs to this server's VMID (prevents
  // restoring another customer's backup by guessing a volid).
  let owned: ServerBackup[];
  try {
    owned = await listBackupsForServer(server);
  } catch {
    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
  }
  if (!owned.some((b) => b.volid === volid)) {
    return { error: "That backup was not found for this server." };
  }

  // DATA SAFETY (critical): `qmrestore --force` over an existing VM calls PVE's
  // destroy_vm first ("avoid zombie disks when restoring over an existing VM"),
  // and destroy_vm frees EVERY volume the vmid owns, `unusedN` entries included.
  // Restoring a backup taken before a volume was attached therefore destroys that
  // volume's data silently, while `Volume.diskName` keeps pointing at the dead
  // volid and billing carries on.
  //
  // Reinstall already refuses for exactly this reason. Restore does the same thing
  // to the same vmid and had no guard at all — same rule, both layers.
  const pinnedVolumes = await db.volume.count({ where: { serverId } });
  if (pinnedVolumes > 0) {
    return {
      error:
        `Restoring replaces this server's disks, which would also destroy the ` +
        `${pinnedVolumes} data volume${pinnedVolumes === 1 ? "" : "s"} assigned to it — ` +
        `including any you have detached. Move or delete them first, then restore.`,
    };
  }

  const idle = await ensureIdle(serverId);
  if (idle.error) return idle;

  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
  await db.auditLog.create({
    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}
"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { requestRestore } from "@/lib/actions-server-ops";
import { fmtBytes } from "@/components/ui/primitives";

type Backup = { volid: string; ctime?: number; size?: number };

function fmtWhen(ctime?: number): string {
  if (!ctime) return "—";
  return new Date(ctime * 1000).toISOString().slice(0, 16).replace("T", " ");
}

/**
 * Self-service restore: lists the server's vzdump backups and lets the owner
 * restore one, enqueuing a BACKUP_RESTORE job. Restore OVERWRITES the current
 * disk, so it is guarded by a typed/explicit confirm.
 */
export function BackupRestore({
  serverId,
  backups,
  unavailable,
  disabled,
}: {
  serverId: string;
  backups: Backup[];
  unavailable?: boolean;
  disabled?: boolean;
}) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pendingVolid, setPendingVolid] = useState<string | null>(null);
  const [isPending, start] = useTransition();

  function restore(b: Backup) {
    const name = b.volid.split("/").pop() ?? b.volid;
    const ok = window.confirm(
      `Restore this server from backup:\n\n${name}\n(${fmtWhen(b.ctime)})\n\n` +
        "This OVERWRITES your server's current disk — every change made since this " +
        "backup will be permanently lost. The server is stopped, restored, then " +
        "started again.\n\nContinue?"
    );
    if (!ok) return;
    setPendingVolid(b.volid);
    start(async () => {
      setError(null);
      const res = await requestRestore(serverId, b.volid);
      setPendingVolid(null);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  }

  return (
    <div className="card p-0">
      <div className="flex items-center justify-between px-4 pt-4">
        <p className="section-label">Restore from backup</p>
      </div>

      {error && <p className="px-4 pt-2 text-sm text-red-400">{error}</p>}

      {unavailable && backups.length === 0 ? (
        <p className="px-4 py-6 text-sm text-amber-300">
          Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
        </p>
      ) : backups.length === 0 ? (
        <p className="px-4 py-6 text-sm text-slate-400">
          No backups to restore yet. Create a backup above first — then you can roll the whole server
          back to it here.
        </p>
      ) : (
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Backup</th>
              <th>Created</th>
              <th className="text-right">Size</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {backups.map((b) => {
              const thisPending = isPending && pendingVolid === b.volid;
              return (
                <tr key={b.volid}>
                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
                  <td className="text-slate-400">{fmtWhen(b.ctime)}</td>
                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
                  <td className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      <a
                        className="btn-secondary px-3 py-1 text-xs"
                        href={`/api/servers/${serverId}/backups/download?volid=${encodeURIComponent(b.volid)}`}
                        // A plain GET download of this server's own archive. The
                        // route re-checks ownership AND that the volid belongs to
                        // this server's vmid, so the link can't reach anyone else's.
                      >
                        Download
                      </a>
                      <button
                        className="btn-danger px-3 py-1 text-xs"
                        disabled={disabled || isPending}
                        onClick={() => restore(b)}
                      >
                        {thisPending ? "Queueing…" : "Restore"}
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      <p className="px-4 py-4 text-xs text-slate-500">
        Restoring overwrites the live disk with the backup&apos;s contents. Take a fresh backup first
        if you might want today&apos;s data back.
      </p>
    </div>
  );
}

